import React, { useState } from 'react';
import React, { useState } from 'react';

// Create your useCounter hook here
function useCounter() {
  // Add count state here
  const [count, setCount] = useState(0);

  // Define increment handler here
  const increment = () => setCount(c => c + 1);

  // Define decrement handler here
  const decrement = () => setCount(c => c - 1);

  // Return the tuple here
  return [count, increment, decrement] as const;
}

// Create your App component here
function App() {
  // Call useCounter and destructure here
  const [count, increment, decrement] = useCounter();

  return null;
}
